def compute(vars):
    values = [vars["v1"], vars["v2"]]
    value = sum(1 for amount in values if amount > 150)
    return {
        "value": value,
        "trace": {
            "values": values,
            "threshold": 150,
            "years_exceeding_threshold": value,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years"
            }
        }
    }
